// BAD: Using Statement + string concatenation to build SQL from untrusted input
// This is vulnerable to SQL injection (vulnerable)
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class UserLookupServletBad extends HttpServlet {
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) {
        String userId = req.getParameter("userId"); // untrusted input from the web
        try (Connection conn = DriverManager.getConnection("jdbc:postgresql://localhost/app", "app", "secret");
             Statement stmt = conn.createStatement()) {

            // Improper API use: concatenating user input directly into the SQL
            String sql = "SELECT id, username, email FROM users WHERE id = " + userId; // unsafe
            ResultSet rs = stmt.executeQuery(sql);

            // Also improper: directly writing DB fields to response without HTML escaping
            while (rs.next()) {
                resp.getWriter().println("User: " + rs.getString("username") + " Email: " + rs.getString("email"));
            }
        } catch (Exception e) {
            // Leaking internals in error messages can disclose sensitive info
            try { resp.getWriter().println("Error: " + e.getMessage()); } catch (Exception ignore) {}
        }
    }
}

***
/*
GOOD: Use PreparedStatement with parameter binding to prevent SQL injection.
Also validate/normalize input, use least-privilege accounts, and encode output.
*/
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.nio.charset.StandardCharsets;

public class UserLookupServletGood extends HttpServlet {
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) {
        resp.setCharacterEncoding(StandardCharsets.UTF_8.name());
        String userIdParam = req.getParameter("userId");

        // Validate input early: ensure it's a numeric ID
        Integer userId = null;
        try {
            userId = Integer.valueOf(userIdParam);
        } catch (Exception ex) {
            safeWrite(resp, "Invalid user id.");
            return;
        }

        // Use a least-privilege DB user and configure timeouts
        try (Connection conn = DriverManager.getConnection("jdbc:postgresql://localhost/app", "app_ro", "secret");
             PreparedStatement ps = conn.prepareStatement(
                     "SELECT id, username, email FROM users WHERE id = ?")) {

            // Proper API use: bind parameters instead of concatenation
            ps.setInt(1, userId);

            try (ResultSet rs = ps.executeQuery()) {
                if (!rs.next()) {
                    safeWrite(resp, "User not found.");
                    return;
                }
                // Encode output to avoid XSS when reflecting data in HTML
                String username = htmlEscape(rs.getString("username"));
                String email = htmlEscape(rs.getString("email"));
                safeWrite(resp, "User: " + username + " Email: " + email);
            }
        } catch (Exception e) {
            // Log server-side; return generic message to clients
            safeWrite(resp, "An error occurred.");
        }
    }

    // Minimal HTML encoder to prevent reflected XSS in this demo
    private static String htmlEscape(String s) {
        if (s == null) return "";
        return s.replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("\"", "&quot;")
                .replace("'", "&#x27;");
    }

    private static void safeWrite(HttpServletResponse resp, String msg) {
        try { resp.getWriter().println(msg); } catch (Exception ignored) {}
    }
}

