// BAD: Insecure Java code using string concatenation for SQL and trusting user input (SQL Injection)
/*
 This code is vulnerable: it concatenates untrusted input directly into an SQL query,
 allowing attackers to inject arbitrary SQL.
*/
import java.sql.*;
import javax.servlet.http.*;

public class UserLookupServlet extends HttpServlet {
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) {
        String userId = req.getParameter("id"); // unvalidated user input
        // vulnerable: improper API usage (Statement + string concatenation)
        String sql = "SELECT username, email FROM users WHERE id = " + userId;

        try (Connection conn = DriverManager.getConnection("jdbc:db://host/app", "u", "p");
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) {

            while (rs.next()) {
                resp.getWriter().println("User: " + rs.getString("username"));
            }
        } catch (Exception e) {
            // Leaks internal details to the client
            try { resp.getWriter().println("Error: " + e.getMessage()); } catch (Exception ignore) {}
        }
    }
}

***
/**
 GOOD: Secure Java code using PreparedStatement with placeholders, input validation,
 least-privilege error handling, and safe response formatting.
*/
import java.sql.*;
import javax.servlet.http.*;
import java.util.regex.Pattern;

public class UserLookupServletSecure extends HttpServlet {
    private static final Pattern NUMERIC = Pattern.compile("^\\d{1,10}$");

    protected void doGet(HttpServletRequest req, HttpServletResponse resp) {
        String userId = req.getParameter("id");

        // Validate and constrain input early (defense-in-depth)
        if (userId == null || !NUMERIC.matcher(userId).matches()) {
            sendSafeError(resp, HttpServletResponse.SC_BAD_REQUEST, "Invalid id");
            return;
        }

        String sql = "SELECT username, email FROM users WHERE id = ?"; // parameterized query

        try (Connection conn = DriverManager.getConnection("jdbc:db://host/app", "u", "p");
             PreparedStatement ps = conn.prepareStatement(sql)) {

            ps.setInt(1, Integer.parseInt(userId)); // bind safely as an integer

            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    // Encode output if rendering into HTML in real apps
                    resp.getWriter().println("User: " + rs.getString("username"));
                }
            }
        } catch (SQLException e) {
            // Do not leak internals; log server-side, return generic message
            sendSafeError(resp, HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "An error occurred");
        } catch (Exception e) {
            sendSafeError(resp, HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "An error occurred");
        }
    }

    private void sendSafeError(HttpServletResponse resp, int status, String message) {
        try {
            resp.setStatus(status);
            resp.getWriter().println(message);
        } catch (Exception ignore) {}
    }
}

